-- Generated from PDF text extraction; source text is stored in nodes.content.
-- PostgreSQL schema: one row per source PDF, nodes stored as JSONB.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY, title TEXT NOT NULL, original_title TEXT, document_type TEXT NOT NULL, year_bs INTEGER NOT NULL, year_ad INTEGER NOT NULL, total_pages INTEGER NOT NULL, nodes JSONB NOT NULL, source_filename TEXT NOT NULL
);

INSERT INTO legal_documents (id,title,original_title,document_type,year_bs,year_ad,total_pages,nodes,source_filename) VALUES ($CODEx5bfe7dcbd6$doc_land_revenue_act_2034_1978_2034_land_revenue_act_2034_pdf$CODEx5bfe7dcbd6$,$CODExdd20afe835$Land Revenue Act, 2034 (1978)$CODExdd20afe835$,NULL,$CODEx76f3b5a717$act$CODEx76f3b5a717$,2034,1978,23,$CODEx0d5598390e$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommission.gov.np\nLand Revenue Act, 2034 (1978)\nDate of Authentication and Publication\n2034.9.18 (2 Jan. 1978)\nAmendments:", "children": []}, {"tier": 1, "nodeType": "section_group", "identifier": "Sections", "title": "Sections", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Land Revenue (First Amendment) Act, 2040", "content": "(1983) 2040.7.13 (30 Oct. 1983)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Administration of Justice (Fourth", "content": "Amendment) Act, 2043 (1986) 2043.7.24 (10 Nov. 1986)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "Land Revenue (Second Amendment) Act,", "content": "2045 (1988) 2045.6.26 (12 Oct. 1988)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Land Revenue (Third Amendment) Act,", "content": "2046 (1989) 2046.7.11 (27 Oct. 1989)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Finance Related Some Nepal Acts", "content": "(Amendment) Act, 2047 (1990) 2047.8.27 (13 Dec. 1990)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Administration of Justice Act, 2048 (1991) 2048.2.16 (30 May, 1991)", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Land Revenue (Fourth Amendment) Act,", "content": "2049 (1992) 2049.9.8 (23 Dec. 1992)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Land Revenue (Fifth Amendment) Act,", "content": "2054 (1997) 2054.8.26 (11 Dec. 1997)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Republic Strengthening and Some Nepal", "content": "Laws Amending Act, 2066 (2010)1 2066.10.7 (21 Jan. 2010)\n1\nThis Act came into force on 15 Jestha 2065(28 June 2008) and \"Prasasti\" and the word \"Kingdom\"\nhas been deleted.\n1\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\nAct Number 25 of the Year 2034 (1978)\nAn Act Made to Provide for Land Revenue\nPreamble: Whereas, it is expedient to amend and consolidate the provisions\nrelating to collection and recovery of the land revenue and to make some\nadditional provisions on cultivation of land;\nNow, therefore, be it enacted by His Majesty King Birendra Bir Bikram\nShah Dev on the advice and with the consent of Rastriya Panchayat.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -1", "title": "Chapter -1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short Title, Extent and Commencement: (1) This Act may be called", "content": "as the \"Land Revenue Act, 2034 (1978).\"\n(2) It shall extend throughout Nepal.\n(3) It shall commence in such District and on such date as may be\nspecified by Government of Nepal, by a Notification published in the Nepal\nGazette. 2", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions: Unless the subject or the context otherwise requires, in this", "content": "Act,-\n(a) \"Land Revenue Office\" means the office established pursuant to\nSection 3.\n(b) \"Land Revenue\" means the land revenue and any other revenue\nsimilar thereto required to be paid by a land owner to Government of\nNepal pursuant to the prevailing Nepal Law, and it also includes any\n2 Notice regarding the date of commencement mentioned at the last page.\n2\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\nfee (penalty) payable for non-payment of the land revenue within the\ntime-limit referred to in this Act.\n(b1) 3 \"Land Revenue Officer\" means the Chief Land Revenue Officer,\n4........., Land Revenue Officer or in-charge of the Land Revenue\nOffice as may be appointed by Government of Nepal to exercise the\npowers of the Land Revenue Officer pursuant to this Act.\n(b2)5 \"Government land\" means a land in which road, street, railway and\ngovernmental building, house or office is situated, and this term\nincludes forest, jungle, river, stream, canal, lake, pond and bank\nthereof, canal, ditch, barren, uncultivated or other land, steep, sandy\nland under control of the Government of Nepal and also a land as\nspecified as a government land by the Government of Nepal upon\npublishing a notice in the Nepal Gazette from time to time.\n(b3) 6 \"Public land\" means a road, well, water bank, pond and bank\nthereof, cattle exit, pasture land, graveyard, grave, inn, rest house,\nshrine, religious pray land, monument, temple, junction, sewerage,\nopen public place, exhibition and fair place, public entertainment\nand sports place that has remained in use since ancient time and\nbelong to the public not to any individual, and also a land as\nspecified as a public land by the Government of Nepal upon\npublishing a notice in the Nepal Gazette from time to time.\n(c) \"Year\" means a fiscal year.\n(d) \"Prescribed\" or \"as prescribed\" means prescribed or as prescribed in\nthe Rules framed under this Act.\n3\nInserted by Fourth Amendment.\n4\nDeleted by Fifth Amendment.\n5 Inserted by the Fifth Amendment.\n6 Inserted by the Fifth Amendment.\n3\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter - 2", "title": "Chapter - 2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "Establishment of Land Revenue Office: (1) Government of Nepal", "content": "shall, 7as per necessity establish the Land Revenue Officer in each District.\n8(1a) The Land Revenue Officer may delegate any or all of his/her\npowers to any officer level employee subordinate to him/her subject to the\nexercising of such power under his/her general supervision and control.\n(2) The Revenue Office and Funds and Collection Offices\nmaintained at the time of commencement of this Act shall ipso facto be\nconverted into the Land Revenue Office after the commencement of this\nAct.\n(3) After the commencement of this Act, the Land Revenue Offices\nshall carry on the functions started by the Revenue Office or Fund and\nCollection Office, immediately at the time of commencement of this Act\nwhich are yet to be completed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Devolution of Functions of Land Administration on Land Reform", "content": "Officer and Land Revenue Office: (1) The Land Administration Office\nand Land Administrators maintained at the time of commencement of this\nAct shall ipso facto be converted into Land Reform Office and Land\nReform Officers respectively after the commencement of this Act; and the\nfunctions under the Act relating to Land, 2021 (1963) shall be carried out\nby the Land Reform Office or Land Reform Officer under that Act, after\nthe commencement of this Act.\n7\nAmended by Fourth Amendment.\n8\nInserted by Fourth Amendment.\n4\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\n(2) After the commencement of this Act, the functions under the\nLands Act, 2021 (1963) started by the Land Administration Office or Land\nAdministrator under the Land Administration Act, 2024 (1966) at the time\nof commencement of this Act which are but yet to be completed shall be\ncarried on by the Land Reform Office or Land Reform Officer pursuant to\nthe Lands Act, 2021 (1963), after the commencement of this Act.\n(3) The functions other than those referred to in Sub-section (2)\nhaving been started by the Land Administration Office or Land\nAdministrator pursuant to the Land Administration Act, 2024 (1966) at the\ntime of commencement of this Act which are but yet to be completed shall\nbe carried out by the Land Revenue Office pursuant to this Act, after the\ncommencement of this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Land Revenue Office to carry out functions to be carried out by", "content": "Revenue Office, Fund and Collection Office or Land\nAdministration Office Pursuant to Other Nepal Law: The function\nto be carried out by the Revenue Office, Fund and Collection office or\nLand Administration Office pursuant to other Nepal Law prevailing\nimmediately at the time of commencement of this Act shall be carried out\nby the Land Revenue Office subject to Section 4 after the commencement\nof this Act; and the functions to be carried out by the In-charge of the\nRevenue Office, Fund and Collection Office or Land Administrator shall\nbe carried out by the In-charge of the Land Revenue Office and references\nto such office or authority made in those laws shall be deemed to refer to\nthe Land Revenue Office or In-charge of the Land Revenue Office.\n5\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter- 3", "title": "Chapter- 3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "6", "title": "Registration of Land: (1) The Land Revenue Office shall register each", "content": "land within the District in such a manner as may be prescribed.\n(2) In maintaining a registration book for the purpose of Sub-section\n(1), it shall be maintained according to the landowner registration record\nprepared in the land survey and measurement in a place where such survey\nand measurement has been done and according to the records maintained in\nthe Land Revenue Office or the records received from the Land Reform\nOffice or other offices in a place where the land survey and measurement\nhas not been done.\nProvided that, in respect of the land to which any other person is\nentitled because of death of the registration holder or transferrable of title\nby such holder, the Land Registration Office shall as per necessity dispatch\na mission to register the land in the name of such person entitled to the land\nand maintain up-to-date records (inventory).\n9(3) In maintaining the land registration book pursuant to Sub-\nsection (2), each Land Revenue Office may require the concerned land\nholders to furnish such details as prescribed and it shall be the duty of each\nland-holder to provide the details so required.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Special Provision Relating to Registration of Land: (1) In", "content": "maintaining the registration book pursuant to Sub-section (2) of Section 6,\nin cases where the survey measurement of any land has been omitted in\ndoing survey under the Land (Survey and Measurement) Act, 2019 (1962),\nthe Land Revenue Office may, with the consent of the Survey Department\n9\nInserted by Fourth Amendment.\n6\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\nand on the 10recommendation of the prescribed committee get the survey\nmeasurement of that land done and register it accordingly.\n11(1a) Notwithstanding anything contained in other Sections of this\nAct, if Government of Nepal deems it necessary, it may, by notification\npublished in the Nepal Gazette for a commission or committee comprising\none chairperson and a maximum of four members in order to resolve any\nproblem arisen in respect of registration of the land belonging to any\nperson, class or area and make decision on the registration of land; and the\nfunctions, duties and powers of the commission or committee shall be as\nspecified in the mode of formation of 12such commission or committee.\n13(2) In cases where any land surveyed and measured pursuant to the\nLand (Survey and Measurement) Act, 2019 (1962) has been omitted only to\nbe registered, the Land Revenue Office may, on the recommendation of the\nprescribed committee, also register such land by making necessary inquiry\ninto the previously existing registration, land revenue as well as possession\nof that land.\n14(2a) …………..\n(3) In the event of differences in the name, surname, address, age of\nlandholder 15or name, surname of his or her father, grand-father, husband or\nfather-in-law, plot number, area or type of the land or dual registration, the\nLand Revenue Office may hold necessary inquiry and maintain the\nregistration by correcting such matter.\n10\nAmended by Fourth Amendment.\n11\nInserted by Fourth Amendment.\n12\nAmended by Fifth Amendment.\n13\nAmended by Fifth Amendment.\n14\nDeleted by Fourth Amendment.\n15 Inserted by Fifth Amendment.\n7\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\n7A.16 Same Landowner Indication Number can be given: The Land\nRevenue Department may make necessary provision in a manner that the\nsame landowner indication number may be given to all lands in his or her\nname within the State of Nepal.\n17", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Registration, Transmission, Dakhil Kharej and stricking out the", "content": "Record: (1) The Land Revenue Office shall carry out the functions of\nregistration, transmitting and crossing off the records of a deed pursuant to\nthe prevailing laws.\n(2) For the purposes of setting out the amount in a deed to be\nregistered, the prescribed committee shall determine the minimum\nvalue of the land within the concerned area.\n(3) In registering or transmitting the land based on the deed of\ncompromise executed pursuant to the laws in force, the Land Revenue\nOffice shall register or transmit such a land only when the previous\nregistration, record or Numbari of the concerned land is verified.\n(4) If an application is made by the concerned person for the\nregistration of the land owned by a person for the public purposes, the\nLand Revenue Office may cross off the name of that person in relation\nto that land, on the recommendation of the prescribed committee.\n(5) In the event of alteration in the records of the land subject to\ntenancy or to action of ceiling, the Land Revenue Office has to give a\nnotice thereof to the Land Reform Office.\n16 Inserted by the Fifth Amendment.\n17\nAmended by Fifth Amendment.\n8\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\n8A.18 To up-date Survey and Map: (1) If the survey and map has to be\namended in accordance with the registration set pursuant to Sections 7 and\n8, the Land Revenue Office has to write to the concerned 19Maintenance\nSurvey Section; and after it has been so written, the 20Maintenance Survey\nSection has to make necessary amendment to the survey and map.\n21\n8B. To Withhold or Release House and Land: (1) If any house or land has\nto be withheld owing to dispute thereof or for any other reason, the Land\nRevenue Office may withhold such a house or land.\n(2) If any office, court or government office writes to withhold\nany house or land or to release the withholding of any house or land\npursuant to the laws in force, the Land Revenue Office shall withhold or\nrelease such a house or land as so written.\n(3) If any bank, financial institution established pursuant to the\nlaw in force or local body writes to withhold any house or land or to\nrelease the withholding of any house or land in the course of its\nfinancial transactions, the Land Revenue Office shall withhold or release\nsuch a house or land as prescribed. In so withholding or releasing the\nwithholding, the Land Revenue Office shall collect the fees as prescribed,\nin the case of a bank or financial institution.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -4", "title": "Chapter -4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "9", "title": "Power to Recover Land Revenue: (1) It hall be the function, duty and", "content": "power of the Land Revenue Office to recover the land revenue.\n18 Inserted by Third Amendment.\n19 Amended by Fourth Amendment.\n20 Amended by Fourth Amendment.\n21 Inserted by Second Amendment.\n9\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\n(2)22 Notwithstanding anything contained in Sub-section (1), the\nGovernment of Nepal may, by publishing a notice in the Nepal Gazette, so\ndelegate powers to any government office or local body to collect land\nrevenue used to be collected by the Land Revenue Office.\n(3)23 The local body has to credit to its fund the amount of land\nrevenue collected by it pursuant to Sub-section (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "To Pay Land Revenue: The land holder of each land in respect of which", "content": "the land revenue has to be paid to Government of Nepal has to pay such\nland revenue of that land each year as may be determined pursuant to the\nprevailing Nepal Law.\n10A.24To Determine the Rate of Land Revenue: Notwithstanding anything\ncontained in Section 10, the Government of Nepal may itself determine the\nrate of land revenue to be paid by the landowner each year pursuant to this\nAct or so specify that the local body may determine the rate of land\nrevenue.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Time Limit for Payment of Land Revenue: Each land holder has to", "content": "pay the land revenue required to be paid by him no later than the 25last day\nof Jestha (about mid June) 13 each year.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Exemption from Land Revenue: Any land holder who pays the land", "content": "revenue no later than the last day of Magha (about mid February) for a year\nshall be exempted from five percent land revenue payable for that year.\n26", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Fee to be levied in Event of Non-payment of land Revenue : In the", "content": "event of payment of the land revenue no later than the Fifteenth day of\nAshad (about mid July) of the year after the expiry of the time limit as\n22 Amended by Fifth Amendment.\n23 Inserted by First Amendment.\n24 Inserted by Fifth Amendment.\n25 Amended by First Amendment.\n26 Amended by First Amendment.\n10\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\nreferred to in Section 11, the land revenue along with Five percent fee shall\nbe recovered.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Inventory of Land in Respect Whereof Land Revenue is Due: The", "content": "Land Revenue Office shall, no later than the 27last day of Ashad (about mid\nJuly) prepare such inventory of the land in respect whereof the land revenue\n28\nhas not been paid and remained due even within the time limit referred to\nin Section 13 as may be prescribed; and 29if any government office or local\nbody has collected land revenue, the government office or local body shall\nprepare such an inventory and forward it to the Land Revenue Office within\nthat period. In cases where the land in respect whereof the land revenue as\nmentioned in that inventory has remained due 30has to be auctioned off, the\nLand Revenue Office shall, no later than the 31last day of Ashwin (about\nmid October), publish a notice in the specified places.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "Power to Withhold Land in Respect Whereof Land Revenue is", "content": "Due: The land of a land holder in respect whereof the land revenue\nspecified in the inventory as referred to in Section 14 is due may be\nwithheld by the Land Revenue Office unless and until the remaining land\nrevenue is paid up or the land is auctioned off to recover the arrears.\nProvided that, the land holder may cultivate the land so withheld as\nusual.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "To Auction Off Land: (1) The Land Revenue Office 32may Auction off", "content": "as prescribed, the plot of land out of the land in respect whereof the land\nrevenue specified in the inventory as referred to in Section 14, in order to\nrecover the land revenue.\n27 Amended by First Amendment.\n28 Amended by First Amendment.\n29 Amended by Fifth Amendment.\n30 Amended by First Amendment.\n31 Amended by Third Amendment.\n32 Amended by First Amendment.\n11\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\n(2)33 In cases where any land has to be auctioned it off pursuant to\nthis Section, the act of such auction shall be started 34from the month of\nMangsir (about mid November).\n(3) If no one agrees to buy the land while auctioning it off pursuant\nto Sub-section (1), the ownership of such land shall devolve on\nGovernment of Nepal; and the land of which ownership has devolved on\nGovernment of Nepal may be sold and disposed off as prescribed.\nProvided that, in spite of devolution of ownership of such land on\nGovernment of Nepal, the tenancy right of the tenant over that land shall\nremain existing.\n(4) Any amount remaining surplus by deducting the arrears of land\nrevenue and a fee of Fifty percent thereof from the proceeds of the auction\nmade under Sub-section (1) shall be refunded to the concerned land holder.\n(5) The monitoring of and other provisions vis-a-vis the land of\nwhich ownership has been devolved on Government of Nepal pursuant to\nSub-section (3) shall be as prescribed pending the sale and disposal of that\nland.\n(6)35 Notwithstanding anything contained in this Section, in cases\nwhere the land revenue is paid from the Sixteenth day of Ashad (about last\nday of June) to the completion of auction sale of the land, the Land\nRevenue Office shall recover the land revenue as well as the fee to be set by\n36Ten per cent per annum from such land holder.\n33 Amended by First Amendment.\n34 Amended by Third Amendment.\n35 Amended by First Amendment.\n36 Amended by Third Amendment.\n12\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\nProvided that, the land revenue shall be recovered by charging\nThirty Five percent fee on the arrears of the land revenue prior to the\ncommencement of this Sub-section.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Power to Extend Time-limit for Payment of Land Revenue: (1)", "content": "Notwithstanding anything contained in Section 11, if Government of Nepal\nthinks that there exists a situation in which the land revenue of any District\nor 37any part of a District or of any person cannot be paid in any year within\nthe time-limit as specified in that Section, it may, by notification published\nin the Nepal Gazette, extend the time limit for payment of the land revenue.\n(2) In cases where the time-limit has been extended pursuant to Sub-\nsection (1), actions referred to in Section 13, 14, 15 and 16 shall be taken\nonly after expiration of the extended time-limit in 38any part of the District\nwhere the time-limit has been extended and in such cases, the time-limit\nshall be set by adding according to time-limit of the number of days so\nextended to the time-limits as referred to in these Sections for taking out\nvarious acts and actions.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Provision of Receipt: The Land Revenue Office or 39 the government", "content": "office or local body recovering the land revenue has to provide a receipt of\nthe recovered land revenue to the payer of the land revenue.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "19", "title": "Provision Relating to Recovery of Land Revenue of Land Beyond", "content": "Ceiling: Pending the transferable, by sale or disposal, of the land beyond\nceiling allowable under the Lands Act, 2021 (1962) after its being acquired\nby the concerned authority, the land revenue of the land subject to\nownership and possession of the existing land holder shall be recovered\n37 Amended by Finance Related Some Nepal Acts (Amendment) Act, 2047\n38 Amended by Finance Related Some Nepal Acts (Amendment) Act, 2047\n39 Amended by Fifth Amendment.\n13\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\nfrom that land holder in a manner that land revenue has to be paid to\nGovernment of Nepal as usual.\nProvided that, the land shall not be auctioned for arrears of land\nrevenue in respect of such land but the arrears of land revenue shall be\ndeducted from compensation to which the land holder is entitled.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter - 5", "title": "Chapter - 5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "20", "title": "Remission of Land Revenue in Cases of River Cutting or Land-", "content": "slide: (1) If any land subject to land revenue is corded by the river or\nstream, or becomes silted or affected by landslide or is covered with\nlandslide and becomes incapable of yielding major crops, the concerned\nlandholder has to make an application setting out details threof to the Land\nRevenue Office in such format and within such time-limit as may be\nprescribed.\nProvided that, in the case of the land having standing crops, the\ncrops should not be harvested prior to holding inquiry pursuant to Sub-\nsection (2).\n(2) The Chief of Land Revenue Office has to hold inquiry into the\nmatters set down in an application made pursuant to Sub-section (1) by\nvisiting the spot in person or dispatching a mission within Thirty days. If, in\nholding such inquiry, it appears to grant remission of the land revenue for\nthat year, the Land Revenue Office has to ascertain by how much\npercentage of the land revenue has to be remitted, remit the same and give\ninformation thereof to the Land Revenue Department within Seven days.\n(3) If it appears from the inquiry as referred to in Sub-section (2) that\nany land has become useless forever, the Land Revenue Office shall make a\n14\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\nsubmission to Government of Nepal to cross off the inventory of that land,\nand Government of Nepal shall, if it deems reasonable, order the Land\nRevenue Office to cross off the inventory of that land.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "Remission of Land Revenue in case of Non-yielding of Crops", "content": "Owing to Drought or Other Natural Calamity: (1) If the 40major\ncrops are destroyed in any area in any year owing to drought or hailstone or\ngrass hopper or flood or any other natural calamity, the Land Revenue\nOffice may, if it deems it necessary to remit land revenue fully or partly,\nupon holding necessary inquiry, make a submission, along with its opinion,\nto Government of Nepal.\n(2) If submission is made pursuant to Sub-section (1) or if\nGovernment of Nepal comes to know such situation in any manner,\n41........................... Government of Nepal shall remit such land revenue as\nmay be deemed necessary.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -7", "title": "Chapter -7", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "24", "title": "Prohibition on Registration or Cultivation of Public or", "content": "Governmental Land: (1) No one shall register in his or her name or\ncultivate, or cause to be registered or cultivated, any governmental land or\npublic land.\nProvided that, nothing contained in this Sub-section shall be\ndeemed to prevent the making provision by the Government of Nepal\nof a public land for public purposes and a governmental land for any\npurpose that the Government of Nepal deems appropriate.\n(2) Where any person has registered any public land or\ngovernmental land in his or her name and cultivated it prior to or after the\ncommencement of this Section, such registration shall ipso facto be void.\nThe Land Revenue Office or an authority specified by Government of\nNepal shall cross off the registration of such land standing in the name of\nany person.\n43 Amended by Fifth Amendment\n44 Amended by Fifth Amendment\n16\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\n(3) The concerned Land Revenue Office shall register the\ngovernmental land and the public land and update the records as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "Prohibition on Cultivation or non-registered Land not Registered:", "content": "No one shall cultivate or cause to be cultivated the land which has not been\nregistered.\nProvided that, this Section shall not be deemed to prevent such land\nfrom being cultivated after the committee prescribed pursuant to Section 26\nhas given approval to cultivate the land or after the land has been sold and\ndistributed in accordance with the prevailing Nepal law relating to\nresettlement.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Cultivation of not Registered Land by Obtaining Approval: (1)", "content": "Approval has to be obtained from the prescribed committee to cultivate any\nnot registered land.\n(2) Application has to be made to the prescribed committee for\napproval to cultivate the not registered land.\n(3) Only those persons who have not any land of their own up to the\nprescribed ceiling as tenants or land holders shall be entitled to make\napplication pursuant to Sub-section (2).\n(4) Subject to this Act and the Rules, the prescribed committee\nframed under this Act and other prevailing Nepal law may grant approval to\nthe persons as referred to in Sub-section (3) to cultivate the not registered\nland.\n(5) In granting approval by the prescribed committee pursuant to\nSub-section (4), the terms for cultivation of such land and the fee therefor\nshall be as prescribed.\n17\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\nProvided that,-\n(a) Nothing contained in this Section shall empower such\ncommittee to grant approval to cultivate any land\nprohibited from being cultivated or registered pursuant\nto 45Sub-section (1) of Section 24.\n(b) The prescribed committee shall not grant approval to\nany person to cultivate any land incapable of being\nregistered as cultivated presently in the name of such\nperson for any reason.\n(c) If more than one person makes an application for\napproval to cultivate any land, approval shall be\ngranted according to the priority as prescribed.\n(6) Notwithstanding anything contained in this Section, if settlement\nis to be made in the land of any area, Government of Nepal may get the\nland within the specified ceiling sold and distributed pursuant to the\nprevailing Nepal law relating to resettlement.\n(7) In granting approval by the prescribed committee to cultivate the\nland or selling or distributing the land for settlement pursuant to Sub-\nsection (6), the prescribed committee or the concerned authority shall get\nsuch land registered.\n(8) The Land Revenue Office shall implement the decision or order\nmade by the concerned committee or authority under this Section in such\nmanner as prescribed.\n45 Deleted by Fifth Amendment.\n18\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -8", "title": "Chapter -8", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "27", "title": "Recovery of Arrears from Jimidar: The land revenue remaining due", "content": "from the Jimidar (trustee of land) at the time of abolition of Jimidari shall\nbe recovered according to the Jimidari records as a governmental due\npursuant to the prevailing Nepal law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "Punishment to a Person who Causes Obstruction and Hindrance", "content": "in Recovering and Collecting Land Revenue: The Chief of the Land\nRevenue Office may impose a fine of up to Five Hundred Rupees on any\nperson who causes obstruction and hindrance in recovering and collecting\nland revenue.\n29.46 Punishment to a Person who Registers or Cultivates\nGovernmental or Public Land: Any person who registers or cultivates\na governmental land or public land shall be punished by the Land Revenue\nOffice with a fine of One Thousand Rupees to Ten Thousand Rupees, and\nsuch a land shall be made barren.\n29A.47 Punishment to a Person Who Submits False Details: If any person\nsubmits false details with mala fide intention in connection with the\nfunctions and proceedings of the Land Revenue Office pursuant to\nPrevailing Law, such person shall be punished by the Land Revenue Office\nwith a fine upto One Thousand Rupees while deciding such matter.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "Punishment to a Person Who Cultivates Land Without Approval:", "content": "Any person who cultivates or causes to be cultivated any land not registered\nwithout obtaining approval pursuant to Sub-section (4) of Section 26 shall\nbe punished with a fine of a sum not exceeding ten-fold of the amount of\n46 Amended by Fifth Amendment.\n47 Inserted by Fifth Amendment.\n19\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\nland revenue in question from the very year of cultivation of the land under\nthe prevailing Nepal Law, and the In-charge of Land Revenue Office shall\nconfiscate that land, and the land so confiscated shall be dealt with as\nprescribed.\n48", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Appeal: An appeal may be made to the Court of Appeal against any", "content": "decision made by the Land Revenue Office under Sections 7, 8, 8B., 28, 29\nand 30.\nProvided that, no appeal may be made to the Court of Appeal\nagainst any decision made by the Land Revenue Office raising the\nissue of entitlement and ordering that the issue has to be settled by the\ncourt.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "To Have Such Powers as of the Court: While taking actions pursuant", "content": "to this Act, the In-charge of the Land Revenue Office shall have such\npowers in respect of taking statement, issuing summons in the name of the\nparties, procuring evidences and getting documents produced as the court is\nentitled to exercise under the prevailing Nepal Law.\n32A.49Departmental Action: If it appears that actions to be carried out by the\nLand Revenue Office pursuant to this Act have been carried out in a mala\nfide manner, departmental action shall be taken against the concerned\nOfficer or employee.\n32B.50 Power to void acts and actions: If it is learnt, by a petition of anyone or\nfrom any source, prior to the making of a complaint in the court, that a\nserious error has been made by the Land Revenue Officer in making\ntransfer and transmission of land pursuant to this Act and amending the\ndetails as set forth in Sub-section (3) of Section 7, the Director General of\n48 Amended by Fifth Amendment.\n49\nInserted by Fourth Amendment.\n50 Inserted by Fifth Amendment.\n20\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\nLand Revenue Department may void that decision and may decide again\npursuant to law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "33", "title": "Power to Frame Rules: Government of Nepal may frame Rules in order", "content": "to accomplish the objectives of this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "34", "title": "Power to Remove Obstruction: If there occurs any obstruction in the", "content": "implementation of this Act, Government of Nepal may, by a Notification\npublished in the Nepal Gazette, issue necessary orders in order to remove\nsuch obstruction.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "35", "title": "To be Inoperative and Repealed: The following Nepal Laws shall be", "content": "inoperative in the Districts where this Act has commenced, and the said\nNepal Laws shall ipso facto be repealed after this Act has commenced\nthroughout Nepal.\n(a) Land Administration Act, 2024 (1967),\n(b) Land Revenue (Special Provision) Act, 2018 (1962),\n(c) Land Revenue (Remission) Act, 2019 (1963),\n(d) Madesh Malko Sabal,\n(e) Pahada Mal Sabal\n21\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\nDate of commencement of the Act and Districts\n(1) It was specified to commence the Act in the following 27 Districts from 2035-1-1 (14 April, 1978)\nthe Nepal Gazette, 2034-12-14 (27 April 1978):\nIlam, Jhapa, Morang, Sunsari, Udyapur, Saptari, Siraha, Sindhuli, Dhanusha, Mahottari,\nSarlahi, Rautahat, Bara, Parsa, Chitwan, Bhaktapur, Lalitpur, Kathmandu, Nawalparisi,\nRupandehi, Kapilvastu, Dang, Surkhet, Banke, Bardia, Kailali and Kanchanpur.\n(2) It was specified to commence the Act in the following 5 Districts from 2035-4-1 (16 July 1978)\nthe Nepal Gazette, 2035-2-30 (12 June 1978):\nPanchathar, Dhankuta, Ramechhap, Tanahun and Mustang.\n(3) It was specified to commence the Act in the following 6 Districts from 2036-1-1 (14 April 1979)\nthe Nepal Gazette 2035-12-6 (19 March 1979):\nDadeldhura, Tehrathum, Kavrepalanchowk, Dhading, Palpa and Myagdi.\n(4) It was specified to commence the Act in the following 3 Districts from 2036-8-15 (1 Dec. 1979)\nthe Nepal Gazette 2036-8-17 (3 Dec. 1979):\nMakawanpur, Nuwakot and Kaski.\n(5) It was specified to commence the Act in Rasuwa District from 2038-5-1 (17 Aug. 1981) the Nepal\nGazette 2038-5-1 (17 Aug. 1981).\n(6) It was specified to commence the Act in the following 3 Districts from 2040-4-1 (17 July 1983)\nthe Nepal Gazette 2040-4-1 (17 July 1983):\nSalyan, Baglung and Bhojpur.\n(7) It was specified to commence the Act in the following 3 Districts from 2041-4-1 (16 July 1984)\nthe Nepal Gazette, 2041-4-1 (16 July 1984):\nGorkha, Gulmi and Syangja.\n(8) It was specified to commence the Act in the following 3 Districts from 2043-4-1 (16 July 1986)\nthe Nepal Gazette 2043-3-9 (23 June 1986):\nParbat, Arghakhanchi and Darchula.\n(9) It was specified to commence the Act in the following 2 Districts from 2045-4-1 (16 July, 1988)\nthe Nepal Gazettes, 2045-3-27 (11 July 1988):\nLamjung and Khotang.\n(10) It was specified to commence the Act in the following 2 Districts from 2046-4-1 (16 July 1989)\nthe Nepal Gazette, 2046-3-26 (10 July 1989):\n22\nwww.lawcommission.gov.np\nwww.lawcommission.gov.np\nDoti and Taplejung.\n(11) It was specified to commence the Act in the following 5 Districts from 2047-4-1 (10 July 1990)\nthe Nepal Gazette, 2047-4-1 (16 July 1990):\nOkhaldhunga, Sindhupalchowk, Manang, Jajarkot and Phuthan.\n(12) It was specified to commence the Act in the following 2 Districts from 2048-4-1 (17 July 1991)\nthe Nepal Gazette, 2048-4-1 (17 July 1991):\nAccham and Baitadi.\n(13) It was specified to commence the Act in the following 2 Districts from 2051-4-1 (16 July 1994)\nthe Nepal Gazette, 2051-4-1 (16 July 1994):\nBajura and Dailekh.\n(14) It was specified to commence the Act in the Sankhuwasabha District from 2052-5-1 (17 Aug.\n1995) the Nepal Gazette, 2052-5-1 (17 Aug. 1995).\n(15) It was specified to commence the Act in the Solukhumbu District from 2053-7-1 (17 Oct. 1996)\nthe Nepal Gazette, 2053-7-1 (17 Oct. 1996).\n(16) It was specified to commence the Act in the following 8 Districts from 2054-5-1 (17 Aug. 1997)\nthe Nepal Gazette, 2054-4-30 (14 Aug. 1997):-\nRukum, Rolpa, Bajhang, Kalikot, Humla, Mugu, Dolpa and Dolakha.\n(17) It was specified to commence the Act in the Jumla District from 2056-8-15 (1 Dec. 1999) the\nNepal Gazette, 2056-8-13 (29 Nov. 1999).\n23\nwww.lawcommission.gov.np", "children": []}]}]$CODEx0d5598390e$::jsonb,$CODEx65cc311ed5$Land Revenue Act, 2034.pdf$CODEx65cc311ed5$) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, original_title=EXCLUDED.original_title, document_type=EXCLUDED.document_type, year_bs=EXCLUDED.year_bs, year_ad=EXCLUDED.year_ad, total_pages=EXCLUDED.total_pages, nodes=EXCLUDED.nodes, source_filename=EXCLUDED.source_filename;
